// Retrieve all 5 contacts from the previous node
const contacts = $('Fetch Leads').all();

return contacts.map(contact => {
  const props = contact.json.properties;
  return {
    json: {
      argument: {
        LinkedinUrl: props.hs_linkedin_url,
        name: props.firstname,
        company: props.company,
        jobtitle: props.jobtitle,
        industry: props.industry,
        company_information: props.company_information
      }
    }
  }
});
